SELECT s.city, CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(i.last_restock) AS first_last_restock, MAX(i.last_restock) AS last_last_restock FROM inventory i JOIN products p ON i.product_id = p.id JOIN suppliers s ON p.supplier_id = s.id WHERE i.product_id IN (4, 6) GROUP BY s.city, CASE WHEN s.rating >= 4.3 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END
